changeSet.sql:
CREATE TABLE am_staging_hadith ( hadith_id varchar(20) PRIMARY KEY, book_id integer NOT NULL, hadith_serial_id bigint NOT NULL, book_name text, hadith_type varchar(50), chapter text, sub_chapter text, raw jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now() ); CREATE INDEX idx_am_staging_hadith_book ON am_staging_hadith(book_id); CREATE UNIQUE INDEX idx_am_staging_hadith_serial ON am_staging_hadith(hadith_serial_id);
CREATE TABLE am_staging_narrator ( narrator_id bigint PRIMARY KEY, full_name text, grade text, level text, raw jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE am_staging_explanation ( es_id varchar(100) PRIMARY KEY, hadith_id varchar(20) NOT NULL, book_name text, author text, raw jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now() ); CREATE INDEX idx_am_staging_explanation_hadith ON am_staging_explanation(hadith_id);
CREATE TABLE am_staging_ruling ( es_id varchar(100) PRIMARY KEY, hadith_id varchar(20) NOT NULL, ruler text, ruler_dod integer, narrations_type varchar(30), raw jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now() ); CREATE INDEX idx_am_staging_ruling_hadith ON am_staging_ruling(hadith_id);
CREATE TABLE am_crawl_checkpoint ( index_name varchar(50) PRIMARY KEY, status varchar(20) NOT NULL DEFAULT 'IDLE' CHECK (status IN ('IDLE','RUNNING','PAUSED','FAILED','COMPLETED')), last_sort_value bigint, fetched_count bigint NOT NULL DEFAULT 0, total_hits bigint, error text, started_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now() );

rollback.sql:
DROP TABLE IF EXISTS am_crawl_checkpoint;
DROP TABLE IF EXISTS am_staging_ruling;
DROP TABLE IF EXISTS am_staging_explanation;
DROP TABLE IF EXISTS am_staging_narrator;
DROP TABLE IF EXISTS am_staging_hadith;
